#!/usr/bin/env python3
from pathlib import Path

P = Path('writing/benevolent_outsider_draft_04_method_primitive_1921_1933.md')
s = P.read_text(encoding='utf-8')

old_para = "By 13 November 1932, thirteen months after the October 1931 letter, the exchange was still active. Malinowski thanked Huizinga for sending his article on the relation of the poetic and the theological in Alanus de Insulis, and three days later Huizinga answered him. Malinowski replied again on 27 November. Huizinga wrote on 1 December about Malinowski’s health; on 3 December the correspondence inventory records two further letters, one in each direction.[^18] The surviving record therefore contains six direct letters in little more than three weeks. What had looked like a thin coda to the 1931 institutional dispute was in fact another concentrated period of scholarly and personal exchange."
new_para = "By 13 November 1932, thirteen months after the October 1931 letter, the exchange was still active. Malinowski thanked Huizinga for sending his article on the relation of the poetic and the theological in Alanus de Insulis, and three days later Huizinga answered him. The article itself asked how Alanus’s allegorical figures stood between conscious conviction and `gedankenlose Spielerei`, insisting that the two did not lie cleanly separated in the human mind.[^18] Malinowski replied again on 27 November. Huizinga wrote on 1 December about Malinowski’s health; on 3 December the correspondence inventory records two further letters, one in each direction. The surviving record therefore contains six direct letters in little more than three weeks. What had looked like a thin coda to the 1931 institutional dispute was in fact another concentrated period of scholarly and personal exchange."
if s.count(old_para) != 1:
    raise SystemExit(f'expected exactly one 1932 coda paragraph, found {s.count(old_para)}')
s = s.replace(old_para, new_para, 1)

old_note = "[^18]: The 2019 *Inventory of the Correspondence of Johan Huizinga* records the dense sequence Malinowski → Huizinga, 13 November 1932; Huizinga → Malinowski, 16 November [951]; Malinowski → Huizinga, 27 November [952]; Huizinga → Malinowski, 1 December; Huizinga → Malinowski, 3 December; and Malinowski → Huizinga, 3 December. The unpublished Huizinga letter of 3 December begins by referring to ‘the fact that I was going to defend you’, but the object and context of that defence are not established by the public inventory and are not used in the body. The 30 January 1933 Malinowski-to-Huizinga letter is unpublished Yale material already controlled in the pair apparatus; it discusses Malinowski’s Dutch, a possible contribution to *De Gids*, and Huizinga correcting his Dutch style. Its absence from the public 2019 inventory is treated as an inventory-visibility discrepancy, not as grounds to delete an independently archive-controlled letter. The exact Yale call/locator should be added before publication."
new_note = "[^18]: The 2019 *Inventory of the Correspondence of Johan Huizinga* records the dense sequence Malinowski → Huizinga, 13 November 1932; Huizinga → Malinowski, 16 November [951]; Malinowski → Huizinga, 27 November [952]; Huizinga → Malinowski, 1 December; Huizinga → Malinowski, 3 December; and Malinowski → Huizinga, 3 December. The article Malinowski thanked Huizinga for was Johan Huizinga, `Über die Verknüpfung des Poetischen mit dem Theologischen bei Alanus de Insulis` (1932), reprinted in *Verzamelde Werken* IV; DBNL TEI `sources/dbnl/verzamelde_werken/huiz003verz05_01.xml`, especially pp. 64–65. Huizinga there locates a `geistige Zone` between `bewusste Überzeugung` and `gedankenlose Spielerei mit ornamentalen Wendungen` and says such things do not lie `so sauber geschieden und so scharf umrissen` in a human mind. The unpublished Huizinga letter of 3 December begins by referring to ‘the fact that I was going to defend you’, but the object and context of that defence are not established by the public inventory and are not used in the body. The 30 January 1933 Malinowski-to-Huizinga letter is unpublished Yale material already controlled in the pair apparatus; it discusses Malinowski’s Dutch, a possible contribution to *De Gids*, and Huizinga correcting his Dutch style. Its absence from the public 2019 inventory is treated as an inventory-visibility discrepancy, not as grounds to delete an independently archive-controlled letter. The exact Yale call/locator should be added before publication."
if s.count(old_note) != 1:
    raise SystemExit(f'expected exactly one note 18, found {s.count(old_note)}')
s = s.replace(old_note, new_note, 1)

P.write_text(s, encoding='utf-8')
print('patched Draft 04: opened 1932 Alanus dispatch into its conviction/Spielerei boundary')
